import {simulateGame,defaultConfig,catalog,clock,status,delay,reason,costs,END,placeName} from './game-sim.mjs';
import {initFloor,updateFloor} from './floor.mjs';
const $=id=>document.getElementById(id);const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);const clone=x=>structuredClone(x);
let config=defaultConfig(),t=0,playing=false,speed=5,selected='OR1',filter='all',last=performance.now(),s,runNumber=0,history=[];
try{const saved=JSON.parse(localStorage.getItem('clara-neuro-game')||'null');if(saved?.schema===1){config=saved.config;history=saved.history||[];runNumber=Math.max(0,...history.map(h=>h.number||0))}}catch{}
initFloor($('map'));
function persist(){try{localStorage.setItem('clara-neuro-game',JSON.stringify({schema:1,config,history:history.slice(0,10)}))}catch{}}
function pause(){playing=false;last=performance.now()}
function changed(){pause();t=0;persist();render();$('edit-status').textContent='New setup ready. Clock reset to 08:00; run the day to compare.'}
function buildEditor(){
 $('resource-editor').innerHTML=['staff','equipment'].map(kind=>`<div><h3>${kind==='staff'?'Staff on duty':'Equipment owned'}</h3>${Object.entries(catalog).filter(([,r])=>r.kind===kind).map(([id,r])=>`<div class="resource-row"><div><b>${r.name}</b><small>${kind==='staff'?`${money(r.rate)}/hour each`:`${money(r.purchase)} purchase · ${money(r.maintenance)}/day upkeep`}</small></div><div class="stepper"><button data-count="${id}" data-step="-1" aria-label="Remove ${r.name}">−</button><output id="count-${id}">${config.counts[id]}</output><button data-count="${id}" data-step="1" aria-label="Add ${r.name}">+</button></div></div>`).join('')}</div>`).join('');
 $('requirements').innerHTML=Object.entries(config.types).map(([key,type])=>`<fieldset><legend>${type.name}</legend><label>Duration (min) <input type="number" min="15" max="240" step="5" value="${type.duration}" data-duration="${key}" aria-label="${type.name} duration"></label>${Object.entries(catalog).map(([id,r])=>`<label>${r.name}<select data-require="${key}:${id}" aria-label="${type.name} requires ${r.name}">${[0,1,2,3].map(n=>`<option value="${n}" ${type.requires[id]===n?'selected':''}>${n===0?'Not required':n}</option>`).join('')}</select></label>`).join('')}</fieldset>`).join('');
 $('case-editor').innerHTML=config.assignments.map((type,i)=>`<label>Case ${'ABCDEF'[i]}<select data-case="${i}" aria-label="Case ${'ABCDEF'[i]} surgery type">${Object.entries(config.types).map(([id,r])=>`<option value="${id}" ${type===id?'selected':''}>${r.name}</option>`).join('')}</select></label>`).join('');
 $('conflict').value=config.conflict;$('capital-mode').value=config.capitalMode;$('delay-rate').value=config.delayRate;$('miss-penalty').value=config.missPenalty;
}
function scenarioKey(c){const x=clone(c);delete x.counts;return JSON.stringify(x)}
function render(){s=simulateGame(config,t);const bill=costs(config,s);$('clock').textContent=clock(t);$('scrub').value=Math.floor(t);$('runstate').textContent=playing?'Running':'Paused';$('play').textContent=playing?'Pause':'Play';$('duration').textContent=`${config.conflict} min`;$('asof').textContent=`As of ${clock(t)}`;
 $('late').textContent=bill.late;$('minutes').innerHTML=Math.floor(bill.delayMinutes)+'<span> min</span>';$('completed').textContent=`${bill.complete}/6`;$('missed').textContent=t>=END?bill.missed:'—';$('total-cost').textContent=money(bill.total);$('goal-state').textContent=t<END?'Finish the day to score this setup':bill.win?'Goal achieved · all 6 cases on time':'Goal not met · inspect delays and resource blockers';$('goal-state').classList.toggle('won',bill.win);
 $('cost-details').innerHTML=[['Payroll accrued',bill.payroll],['Equipment ownership',bill.equipment],['Maintenance accrued',bill.maintenance],['Start delay penalties',bill.delayCost],['Missed-case penalties',bill.penalty]].map(([k,v])=>`<div><span>${k}</span><b>${money(v)}</b></div>`).join('')+`<p class="footnote">Equipment purchase value: ${money(bill.capital)}. ${config.capitalMode==='daily'?'Purchase spread over 1,250 operating days; ownership and maintenance accrue over this 8-hour day.':'Full equipment purchase charged at 08:00; maintenance accrues over the day.'} Staff are paid for all on-duty time, including idle time.</p>`;
 $('setup-warning').textContent=Object.values(config.types).some(type=>Object.values(type.requires).every(n=>n===0))?'A type has no resource requirements. Results reflect your custom game rules.':'Requirements are editable game rules, not clinically sufficient staffing or equipment lists.';
 renderMotion();
 $('schedule').innerHTML=`<div class="axis"><span></span><div class="ticks">${Array.from({length:9},(_,i)=>`<span>${clock(i*60)}</span>`).join('')}</div></div>`+s.cases.map(c=>{const d=delay(c,t);return `<div class="timeline-row"><button class="case-label" data-entity="${c.id}">Case ${c.id}<small>OR ${c.room} · ${c.type==='cranial'?'Cranial':'Spine'}${d?` +${Math.floor(d)}m`:''}</small></button><div class="track"><span class="bar plan" style="left:${c.plan/END*100}%;width:${Math.min(c.duration,END-c.plan)/END*100}%"></span>${d?`<span class="bar delay" style="left:${c.plan/END*100}%;width:${Math.min(d,END-c.plan)/END*100}%"></span>`:''}${c.start!==null&&t>c.start?`<span class="bar actual" style="left:${c.start/END*100}%;width:${(Math.min(t,c.end,END)-c.start)/END*100}%"></span>`:''}<span class="now-line" style="left:${t/END*100}%"></span></div></div>`}).join('');
 renderInspector();const events=s.events.filter(e=>filter==='delay'?['delay','blocked','missed'].includes(e.kind):filter==='movement'?e.kind==='movement':filter==='selected'?matches(e.entity):true).slice().reverse();$('events').innerHTML=events.map(e=>`<div class="event ${['delay','blocked','missed'].includes(e.kind)?'delayed':''}"><time>${clock(e.time)}</time><button data-entity="${e.entity}">${e.entity}</button><span>${e.text}</span></div>`).join('')||'<div class="empty">No matching events yet.</div>';
 renderHistory();
}
function matches(id){if(id===selected)return true;const room=selected.match(/^OR(\d)$/);return room&&s.cases.some(c=>c.id===id&&c.room===+room[1])}
function renderInspector(){let title,desc,facts=[],dep;const c=s.cases.find(c=>c.id===selected),r=s.resources.find(r=>r.id===selected);
 if(c){title=`Case ${c.id} · ${c.name}`;desc=status(c,t);facts=[['Plan / actual',`${clock(c.plan)} / ${c.start===null?'not started':clock(c.start)}`],['Start delay',`${Math.floor(delay(c,t))} min`],['Assigned',c.assigned.join(', ')||'None'],['Requirements',Object.entries(c.requires).filter(([,n])=>n).map(([k,n])=>`${n} ${catalog[k].name}`).join(', ')||'None (custom rules)']];dep=reason(c,s)}
 else if(r){title=`${r.id} · ${catalog[r.type].name}`;desc=r.status;facts=[['Location',placeName(r.location)],['Case',r.owner||'Unassigned'],...(r.motion?[['Route',`${placeName(r.motion.from)} → ${placeName(r.motion.to)}`],['Arrival',clock(r.motion.arrive)]]:[])];dep=r.kind==='staff'?`Paid at ${money(catalog[r.type].rate)}/hour while on duty, even when idle.`:'One case can reserve this unit at a time. Cleaning and transport make it temporarily unavailable.'}
 else {title=placeName(selected);desc='Synthetic neurosurgery floor';const n=+selected.slice(2);const current=s.cases.find(c=>c.room===n&&c.start!==null&&t<c.end)||s.cases.find(c=>c.room===n&&c.start===null&&t>=c.plan);facts=[['Present staff',s.staff.filter(r=>r.location===selected).map(r=>r.id).join(', ')||'None'],['Equipment',s.equipment.filter(r=>r.location===selected).map(r=>r.id).join(', ')||'None']];dep=current?`Case ${current.id}: ${reason(current,s)}`:'Staff and equipment are shared between rooms. Select a case to see its blockers.'}
 $('inspector').innerHTML=`<h2>${title}</h2><p>${desc}</p><dl class="facts">${facts.map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl><div class="dependency">${dep}</div>`;
}
function renderMotion(){const moving=updateFloor(s,t,selected);$('movement-status').textContent=moving.length?moving.join(' · '):'No one in transit · select a case to inspect its dependencies';$('movement-count').textContent=`${moving.length} moving`}
function recordRun(){const final=simulateGame(config,END),bill=costs(config,final),key=scenarioKey(config);const previous=history.find(h=>h.key===key);const result={number:++runNumber,key,config:clone(config),bill,blocked:final.events.filter(e=>e.kind==='blocked').length,delayed:final.events.filter(e=>e.kind==='delay').length};history.unshift(result);history=history.slice(0,10);persist();$('edit-status').textContent=`Run ${result.number} saved. ${previous?`${bill.late-previous.bill.late} change in late cases; ${bill.missed-previous.bill.missed} change in missed cases versus last run with these rules.`:'First run for these rules.'}`;renderHistory()}
function renderHistory(){const key=scenarioKey(config);$('run-history').innerHTML=history.length?`<div class="history-scroll"><table><thead><tr><th>Run</th><th>Staff / units</th><th>Complete</th><th>Blocked starts</th><th>Late cases</th><th>Delay min</th><th>Missed</th><th>Total cost</th><th></th></tr></thead><tbody>${history.map((h,i)=>`<tr><td>#${h.number}${h.key!==key?' · other rules':''}</td><td>${Object.entries(catalog).filter(([,r])=>r.kind==='staff').reduce((a,[k])=>a+h.config.counts[k],0)} / ${Object.entries(catalog).filter(([,r])=>r.kind==='equipment').reduce((a,[k])=>a+h.config.counts[k],0)}</td><td>${h.bill.complete}/6</td><td>${h.blocked}</td><td>${h.bill.late}</td><td>${Math.round(h.bill.delayMinutes)}</td><td>${h.bill.missed}</td><td>${money(h.bill.total)}${h.bill.win?' · on time':''}</td><td><button data-restore="${i}">Load</button></td></tr>`).join('')}</tbody></table></div>`:'<p>No runs yet. Run the full day, then change a resource count and run again. Your last 10 runs stay in this browser.</p>';const eligible=history.filter(h=>h.key===key&&h.bill.win);const best=eligible.slice().sort((a,b)=>a.bill.total-b.bill.total)[0];const fewest=eligible.length?Math.min(...eligible.map(h=>Object.entries(catalog).filter(([,r])=>r.kind==='staff').reduce((a,[k])=>a+h.config.counts[k],0))):null;$('best-run').textContent=best?`Best on-time cost tried: run ${best.number} · ${money(best.bill.total)}. Fewest staff in on-time runs: ${fewest}. This is not proof of a global minimum.`:'Challenge: find the least expensive setup that finishes all 6 cases on time.'}
function setTime(at){pause();t=at;render()}
document.addEventListener('click',e=>{const count=e.target.closest('[data-count]');if(count){const id=count.dataset.count;config.counts[id]=Math.max(0,Math.min(8,config.counts[id]+ +count.dataset.step));$(`count-${id}`).textContent=config.counts[id];changed();return}const restore=e.target.closest('[data-restore]');if(restore){config=clone(history[+restore.dataset.restore].config);buildEditor();changed();return}const entity=e.target.closest('[data-entity]');if(entity){selected=entity.dataset.entity;render()}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.matches('[role=button]')){selected=e.target.dataset.entity;render()}});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.require){const [key,id]=el.dataset.require.split(':');config.types[key].requires[id]=+el.value;changed()}else if(el.dataset.duration){config.types[el.dataset.duration].duration=Math.max(15,Math.min(240,Math.round((+el.value||15)/5)*5));el.value=config.types[el.dataset.duration].duration;changed()}else if(el.dataset.case){config.assignments[+el.dataset.case]=el.value;changed()}});
$('capital-mode').onchange=e=>{config.capitalMode=e.target.value;changed()};$('delay-rate').onchange=e=>{config.delayRate=Math.max(0,Math.min(1000,+e.target.value||0));e.target.value=config.delayRate;changed()};$('miss-penalty').onchange=e=>{config.missPenalty=Math.max(0,Math.min(1000000,+e.target.value||0));e.target.value=config.missPenalty;changed()};$('conflict').oninput=e=>{config.conflict=+e.target.value;changed()};
$('play').onclick=()=>{if(t>=END)t=0;playing=!playing;last=performance.now();render()};$('reset').onclick=()=>setTime(0);$('defaults').onclick=()=>{config=defaultConfig();buildEditor();changed()};$('rewind').onclick=()=>setTime(Math.max(0,t-10));$('next').onclick=()=>setTime(simulateGame(config,END).events.find(e=>e.time>t)?.time??END);$('scrub').oninput=e=>setTime(+e.target.value);$('speed').onchange=e=>speed=+e.target.value;$('run-day').onclick=()=>{pause();t=END;render();recordRun()};$('save-run').onclick=()=>{if(t<END){$('edit-status').textContent='Finish the day before saving a score.';return}recordRun()};$('filter').onchange=e=>{filter=e.target.value;render()};$('about').onclick=()=>$('aboutDialog').showModal();$('closeAbout').onclick=()=>$('aboutDialog').close();
setInterval(()=>{const now=performance.now(),dt=(now-last)*speed/1000;last=now;if(playing){const before=Math.floor(t);t=Math.min(END,t+dt);if(t===END)playing=false;if(Math.floor(t)!==before||!playing)render();else renderMotion()}},40);buildEditor();render();
